// ProuveTech JavaScript - Version sécurisée et complète
(function() {
    'use strict';

    // Configuration
    const CONFIG = {
        API_ENDPOINT: 'https://prouvetech.fr/api/subscribe.php',
        // API_ENDPOINT: 'http://localhost/prouvetechbeta/api/subscribe.php',
        SCROLL_OFFSET: 100,
        DEBOUNCE_DELAY: 300,
        PARALLAX_FPS: 60,
        SESSION_KEY: 'pt_last_submission'
    };

    //Slider
    document.addEventListener('DOMContentLoaded', () => {
        const slides = document.querySelectorAll('.solution-slider .slide');
        const nextBtn = document.querySelector('.slider-btn.next');
        const prevBtn = document.querySelector('.slider-btn.prev');
        let current = 0;

        function showSlide(index) {
            slides.forEach((slide, i) => {
                slide.classList.toggle('active', i === index);
            });
        }

        nextBtn.addEventListener('click', () => {
            current = (current + 1) % slides.length;
            showSlide(current);
        });

        prevBtn.addEventListener('click', () => {
            current = (current - 1 + slides.length) % slides.length;
            showSlide(current);
        });

        // Auto défilement toutes les 5 secondes
        setInterval(() => {
            current = (current + 1) % slides.length;
            showSlide(current);
        }, 5000);
    });


    // Utilitaire pour debounce
    function debounce(func, wait) {
        let timeout;
        return function executedFunction(...args) {
            const later = () => {
                clearTimeout(timeout);
                func(...args);
            };
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
        };
    }

    // Utilitaire pour throttle
    function throttle(func, limit) {
        let inThrottle;
        return function(...args) {
            if (!inThrottle) {
                func.apply(this, args);
                inThrottle = true;
                setTimeout(() => inThrottle = false, limit);
            }
        };
    }

    // Animation on scroll avec Intersection Observer
    function initScrollAnimations() {
        // Vérifier le support de IntersectionObserver
        if (!('IntersectionObserver' in window)) {
            // Fallback pour les anciens navigateurs
            document.querySelectorAll('.fade-in-section').forEach(section => {
                section.classList.add('visible');
            });
            return;
        }

        const observerOptions = {
            threshold: 0.1,
            rootMargin: '0px 0px -100px 0px'
        };

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                    // Une fois visible, on arrête d'observer pour optimiser
                    observer.unobserve(entry.target);
                }
            });
        }, observerOptions);

        // Observer tous les éléments avec animation
        document.querySelectorAll('.fade-in-section').forEach(section => {
            observer.observe(section);
        });
    }

    
    // Smooth scroll pour navigation
    function initSmoothScroll() {
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function(e) {
                e.preventDefault();
                const targetId = this.getAttribute('href');
                
                if (targetId === '#') return;
                
                const target = document.querySelector(targetId);
                
                if (target) {
                    const offsetTop = target.offsetTop - CONFIG.SCROLL_OFFSET;
                    
                    // Utiliser scrollTo avec behavior smooth si supporté
                    if ('scrollBehavior' in document.documentElement.style) {
                        window.scrollTo({
                            top: offsetTop,
                            behavior: 'smooth'
                        });
                    } else {
                        // Fallback pour anciens navigateurs
                        smoothScrollTo(offsetTop, 800);
                    }
                }
            });
        });
    }

    // Fonction de smooth scroll pour anciens navigateurs
    function smoothScrollTo(target, duration) {
        const start = window.pageYOffset;
        const distance = target - start;
        const startTime = performance.now();

        function animation(currentTime) {
            const elapsedTime = currentTime - startTime;
            const progress = Math.min(elapsedTime / duration, 1);
            const easeProgress = easeInOutQuad(progress);
            
            window.scrollTo(0, start + (distance * easeProgress));
            
            if (elapsedTime < duration) {
                requestAnimationFrame(animation);
            }
        }

        function easeInOutQuad(t) {
            return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
        }

        requestAnimationFrame(animation);
    }

    // Parallax effect on mouse move
    function initParallaxEffect() {
        const shapes = document.querySelectorAll('.floating-shape');
        if (shapes.length === 0) return;

        // Vérifier si l'utilisateur préfère les animations réduites
        const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (prefersReducedMotion) return;

        const handleMouseMove = throttle((e) => {
            const x = e.clientX / window.innerWidth;
            const y = e.clientY / window.innerHeight;
            
            shapes.forEach((shape, index) => {
                const speed = (index + 1) * 20;
                const xPos = (x - 0.5) * speed;
                const yPos = (y - 0.5) * speed;
                
                shape.style.transform = `translate(${xPos}px, ${yPos}px)`;
            });
        }, 1000 / CONFIG.PARALLAX_FPS);

        document.addEventListener('mousemove', handleMouseMove, { passive: true });
    }

    // Gestion du formulaire
    function initFormHandler() {
        const form = document.getElementById('betaForm');
        if (!form) return;

        form.addEventListener('submit', handleFormSubmit);

        // // Validation en temps réel pour l'email
        // const emailInput = document.getElementById('email');
        // if (emailInput) {
        //     emailInput.addEventListener('blur', function() {
        //         validateEmail(this);
        //     });
            
        //     emailInput.addEventListener('input', debounce(function() {
        //         validateEmail(this);
        //     }, 500));
        // }

        // Validation des autres champs
        const requiredInputs = form.querySelectorAll('[required]');
        requiredInputs.forEach(input => {
            input.addEventListener('blur', function() {
                validateField(this);
            });
        });

        // Anti-spam: honeypot
        const honeypot = form.querySelector('input[name="website"]');
        if (honeypot) {
            honeypot.style.position = 'absolute';
            honeypot.style.left = '-9999px';
            honeypot.tabIndex = -1;
            honeypot.setAttribute('aria-hidden', 'true');
            honeypot.autocomplete = 'off';
        }
    }

    // function validateEmail(input) {
    //     const email = input.value.trim();
    //     if (email && !isValidEmail(email)) {
    //         input.setCustomValidity('Veuillez entrer une adresse email valide');
    //         input.classList.add('invalid');
    //         showFieldError(input, 'Email invalide');
    //     } else {
    //         input.setCustomValidity('');
    //         input.classList.remove('invalid');
    //         hideFieldError(input);
    //     }
    // }

    function validateField(field) {
        if (field.hasAttribute('required') && !field.value.trim()) {
            field.classList.add('invalid');
            showFieldError(field, 'Ce champ est requis');
        } else {
            field.classList.remove('invalid');
            hideFieldError(field);
        }
    }

    function showFieldError(field, message) {
        let errorEl = field.parentElement.querySelector('.field-error');
        if (!errorEl) {
            errorEl = document.createElement('span');
            errorEl.className = 'field-error';
            errorEl.style.cssText = 'color: #ef4444; font-size: 0.875rem; margin-top: 4px; display: block;';
            field.parentElement.appendChild(errorEl);
        }
        errorEl.textContent = message;
    }

    function hideFieldError(field) {
        const errorEl = field.parentElement.querySelector('.field-error');
        if (errorEl) {
            errorEl.remove();
        }
    }

    async function handleFormSubmit(e) {
        e.preventDefault();
        
        const form = e.target;
        const submitBtn = form.querySelector('.submit-btn');
        const btnText = submitBtn.querySelector('.btn-text');
        const btnLoader = submitBtn.querySelector('.btn-loader');
        const formSuccess = form.querySelector('.form-success');
        const formError = form.querySelector('.form-error');
        const errorMessage = form.querySelector('.error-message');
        
        // Vérification honeypot anti-spam
        const honeypot = form.querySelector('input[name="website"]');
        if (honeypot && honeypot.value) {
            console.warn('Spam détecté');
            return false;
        }
        
        // Rate limiting côté client
        const lastSubmission = sessionStorage.getItem(CONFIG.SESSION_KEY);
        const now = Date.now();
        if (lastSubmission && (now - parseInt(lastSubmission)) < 60000) {
            showError(form, formError, errorMessage, 'Veuillez attendre une minute avant de renvoyer le formulaire.');
            return false;
        }
        
        // Validation des champs requis
        if (!form.checkValidity()) {
            form.reportValidity();
            return false;
        }
        
        // Validation personnalisée
        const email = form.querySelector('#email').value;
        if (!isValidEmail(email)) {
            showError(form, formError, errorMessage, 'Veuillez entrer une adresse email valide.');
            return false;
        }
        
        // Show loading state
        btnText.style.display = 'none';
        btnLoader.style.display = 'flex';
        submitBtn.disabled = true;
        submitBtn.style.opacity = '0.7';
        
        // Collecter les données du formulaire
        const formData = new FormData(form);
        
        try {
            const response = await fetch(CONFIG.API_ENDPOINT, {
                method: 'POST',
                body: formData,
                headers: {
                    'X-Requested-With': 'XMLHttpRequest'
                }
            });
            
            const data = await response.json();
            
            if (response.ok && data.success) {
                // Succès
                sessionStorage.setItem(CONFIG.SESSION_KEY, now.toString());
                showSuccess(form, formSuccess);
                
                // Track conversion si Google Analytics est présent
                if (typeof gtag !== 'undefined') {
                    gtag('event', 'conversion', {
                        'event_category': 'engagement',
                        'event_label': 'beta_signup',
                        'value': 1
                    });
                }
                
                // Tracking Facebook Pixel si présent
                if (typeof fbq !== 'undefined') {
                    fbq('track', 'Lead');
                }
                
            } else {
                // Erreur métier
                const errorMsg = data.message || 'Une erreur est survenue. Veuillez réessayer.';
                showError(form, formError, errorMessage, errorMsg);
            }
            
        } catch (error) {
            console.error('Erreur réseau:', error);
            
            // Fallback : enregistrer localement et réessayer plus tard
            const offlineData = {
                formData: Object.fromEntries(formData),
                timestamp: now
            };
            
            try {
                let offlineSubmissions = JSON.parse(localStorage.getItem('pt_offline_submissions') || '[]');
                offlineSubmissions.push(offlineData);
                localStorage.setItem('pt_offline_submissions', JSON.stringify(offlineSubmissions));
                
                showError(
                    form, 
                    formError, 
                    errorMessage, 
                    'Inscription impossible.'
                );
            } catch (storageError) {
                showError(form, formError, errorMessage, 'Erreur de connexion. Vérifiez votre connexion internet et réessayez.');
            }
            
        } finally {
            // Reset button state
            setTimeout(() => {
                btnText.style.display = 'block';
                btnLoader.style.display = 'none';
                submitBtn.disabled = false;
                submitBtn.style.opacity = '1';
            }, 1000);
        }
    }

    function showSuccess(form, formSuccess) {
        // Animation de disparition des champs
        const formGroups = form.querySelectorAll('.form-group');
        const checkboxGroups = form.querySelectorAll('.checkbox-group');
        const submitBtn = form.querySelector('.submit-btn');
        
        // Fade out effect
        [...formGroups, ...checkboxGroups].forEach((el, index) => {
            setTimeout(() => {
                el.style.transition = 'opacity 0.3s, transform 0.3s';
                el.style.opacity = '0';
                el.style.transform = 'translateY(-10px)';
                
                setTimeout(() => {
                    el.style.display = 'none';
                }, 300);
            }, index * 50);
        });
        
        // Cacher le bouton
        setTimeout(() => {
            submitBtn.style.transition = 'opacity 0.3s';
            submitBtn.style.opacity = '0';
            setTimeout(() => {
                submitBtn.style.display = 'none';
                
                // Afficher le message de succès
                formSuccess.style.display = 'block';
                formSuccess.style.animation = 'fadeInScale 0.5s ease';
                
                // Scroll vers le message
                formSuccess.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 300);
        }, formGroups.length * 50);
        
        // Reset form après délai
        setTimeout(() => {
            form.reset();
        }, 3000);
    }

    function showError(form, formError, errorMessage, message) {
        if (formError && errorMessage) {
            formError.style.display = 'block';
            errorMessage.textContent = message;
            
            // Animation shake
            formError.style.animation = 'shake 0.3s ease';
            
            // Scroll vers l'erreur
            formError.scrollIntoView({ behavior: 'smooth', block: 'center' });
        } else {
            // Fallback alert
            alert(message);
        }
    }

    // Fonction globale pour réinitialiser le formulaire après erreur
    window.resetForm = function() {
        const form = document.getElementById('betaForm');
        if (!form) return;
        
        const formError = form.querySelector('.form-error');
        const formSuccess = form.querySelector('.form-success');
        
        // Cacher les messages
        if (formError) formError.style.display = 'none';
        if (formSuccess) formSuccess.style.display = 'none';
        
        // Réafficher tous les champs
        const allElements = form.querySelectorAll('.form-group, .checkbox-group, .submit-btn');
        allElements.forEach(el => {
            el.style.display = '';
            el.style.opacity = '1';
            el.style.transform = '';
        });
        
        // Reset les champs invalides
        form.querySelectorAll('.invalid').forEach(field => {
            field.classList.remove('invalid');
        });
        
        // Supprimer les messages d'erreur
        form.querySelectorAll('.field-error').forEach(error => {
            error.remove();
        });
    };

    // Validation email regex
    function isValidEmail(email) {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
        return re.test(email.toLowerCase());
    }

    // Navigation sticky avec hide on scroll down
    function initStickyNav() {
        let lastScrollTop = 0;
        const nav = document.querySelector('nav');
        if (!nav) return;
        
        const scrollThreshold = 100;
        let ticking = false;
        
        function updateNav() {
            const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            
            if (Math.abs(lastScrollTop - scrollTop) <= 5) {
                ticking = false;
                return;
            }
            
            if (scrollTop > lastScrollTop && scrollTop > scrollThreshold) {
                // Scrolling down
                nav.style.transform = 'translateY(-100%)';
            } else {
                // Scrolling up
                nav.style.transform = 'translateY(0)';
            }
            
            lastScrollTop = scrollTop <= 0 ? 0 : scrollTop;
            ticking = false;
        }
        
        window.addEventListener('scroll', function() {
            if (!ticking) {
                window.requestAnimationFrame(updateNav);
                ticking = true;
            }
        }, { passive: true });
    }

    // Lazy loading pour les images
    function initLazyLoading() {
        // Support natif du lazy loading
        if ('loading' in HTMLImageElement.prototype) {
            const images = document.querySelectorAll('img[data-src]');
            images.forEach(img => {
                img.src = img.dataset.src;
                img.removeAttribute('data-src');
                if (img.dataset.srcset) {
                    img.srcset = img.dataset.srcset;
                    img.removeAttribute('data-srcset');
                }
            });
        } else {
            // Fallback avec IntersectionObserver
            const imageObserver = new IntersectionObserver((entries, observer) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        const img = entry.target;
                        img.src = img.dataset.src;
                        img.removeAttribute('data-src');
                        if (img.dataset.srcset) {
                            img.srcset = img.dataset.srcset;
                            img.removeAttribute('data-srcset');
                        }
                        img.classList.add('loaded');
                        observer.unobserve(img);
                    }
                });
            });

            document.querySelectorAll('img[data-src]').forEach(img => {
                imageObserver.observe(img);
            });
        }
    }

    // Tentative de renvoi des données offline
    function syncOfflineData() {
        const offlineData = localStorage.getItem('pt_offline_submissions');
        if (!offlineData) return;
        
        try {
            const submissions = JSON.parse(offlineData);
            if (submissions.length === 0) return;
            
            // Essayer de renvoyer les données
            submissions.forEach(async (submission, index) => {
                const formData = new FormData();
                Object.keys(submission.formData).forEach(key => {
                    formData.append(key, submission.formData[key]);
                });
            });
        } catch (error) {
            console.error('Erreur lors de la synchronisation offline:', error);
        }
    }

    // Gestion du focus pour l'accessibilité
    function initAccessibility() {
        // Skip to content link
        const skipLink = document.createElement('a');
        skipLink.href = '#hero';
        skipLink.className = 'skip-to-content';
        skipLink.textContent = 'Aller au contenu principal';
        skipLink.style.cssText = `
            position: absolute;
            left: -9999px;
            z-index: 9999;
            padding: 1em;
            background: #1e3a8a;
            color: white;
            text-decoration: none;
        `;
        skipLink.addEventListener('focus', () => {
            skipLink.style.left = '50%';
            skipLink.style.transform = 'translateX(-50%)';
        });
        skipLink.addEventListener('blur', () => {
            skipLink.style.left = '-9999px';
        });
        document.body.insertBefore(skipLink, document.body.firstChild);
        
        // Gestion du focus pour les modales (si ajoutées plus tard)
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                const openModals = document.querySelectorAll('.modal.open');
                openModals.forEach(modal => {
                    closeModal(modal);
                });
            }
        });
    }

    // Fonction pour fermer les modales (préparation future)
    function closeModal(modal) {
        modal.classList.remove('open');
        const trigger = document.querySelector(`[data-modal-trigger="${modal.id}"]`);
        if (trigger) trigger.focus();
    }

    // Performance monitoring
    function initPerformanceMonitoring() {
        if ('PerformanceObserver' in window) {
            try {
                // Observer les Long Tasks
                const observer = new PerformanceObserver((list) => {
                    for (const entry of list.getEntries()) {
                        // Log ou envoyer à analytics
                        if (entry.duration > 50) {
                            console.warn('Long task detected:', entry.duration + 'ms');
                        }
                    }
                });
                observer.observe({ entryTypes: ['longtask'] });
            } catch (e) {
                // PerformanceObserver non supporté pour longtask
            }
        }
        
        // Log des métriques de performance au chargement
        window.addEventListener('load', () => {
            setTimeout(() => {
                const perfData = performance.getEntriesByType('navigation')[0];
                if (perfData) {
                    const pageLoadTime = perfData.loadEventEnd - perfData.fetchStart;
                    console.log('Page load time:', Math.round(pageLoadTime) + 'ms');
                    
                    // Envoyer à Google Analytics si disponible
                    if (typeof gtag !== 'undefined') {
                        gtag('event', 'timing_complete', {
                            'name': 'load',
                            'value': Math.round(pageLoadTime),
                            'event_category': 'performance'
                        });
                    }
                }
            }, 0);
        });
    }

    // Initialisation principale
    document.addEventListener('DOMContentLoaded', function() {
        // Initialiser tous les modules
        initScrollAnimations();
        initSmoothScroll();
        initParallaxEffect();
        initFormHandler();
        initStickyNav();
        initLazyLoading();
        initAccessibility();
        initPerformanceMonitoring();
        
        // Sync des données offline au chargement
        syncOfflineData();
        
        // Vérifier périodiquement pour les données offline
        setInterval(syncOfflineData, 60000); // Toutes les minutes

        // Protection basique contre le clic droit sur les images
        document.addEventListener('contextmenu', function(e) {
            if (e.target.tagName === 'IMG') {
                e.preventDefault();
                return false;
            }
        });

    });

    // Service Worker pour PWA (optionnel mais recommandé)
    if ('serviceWorker' in navigator && location.protocol === 'https:') {
        window.addEventListener('load', () => {
            navigator.serviceWorker.register('/sw.js')
                .then(registration => {
                    console.log('Service Worker enregistré:', registration.scope);
                })
                .catch(error => {
                    // Service worker non disponible ou erreur
                    console.log('Service Worker non disponible:', error);
                });
        });
    }

    // Export des fonctions utiles globalement
    window.ProuveTech = {
        resetForm: window.resetForm,
        syncOfflineData: syncOfflineData
    };
})();